void initialize_leg_rig(struct Moby *moby, LegRig *rig) __asm__("FUN_L04_002923b8");

void initialize_leg_rig(struct Moby *moby, LegRig *rig) {
    int   joints[6];
    float matrix[4][4];
    int   i;
    int   j;
    int   k;

    for (i = 0; i < 13; i++) {
        if (rig->anims[i]->id < 0) {
            debug_print(invalid_animation_message, i, moby->oclass);
            raise_kernel_trap();
        }
        rig->anims[i]->start = animation_start(moby->class_slot, rig->anims[i]->id);
        rig->anims[i]->len =
            animation_end(moby->class_slot, rig->anims[i]->id) - rig->anims[i]->start;
        if (rig->anims[i]->len != 0.0f) {
            for (j = 0; j < 2; j++) {
                rig->anims[i]->phase[1].span[j] =
                    rig->anims[i]->phase[1].from[j] <= rig->anims[i]->phase[1].to[j]
                        ? rig->anims[i]->phase[1].to[j] - rig->anims[i]->phase[1].from[j]
                        : rig->anims[i]->phase[1].to[j] + rig->anims[i]->len -
                              rig->anims[i]->phase[1].from[j];
                rig->anims[i]->phase[0].span[j] =
                    rig->anims[i]->phase[0].from[j] <= rig->anims[i]->phase[0].to[j]
                        ? rig->anims[i]->phase[0].to[j] - rig->anims[i]->phase[0].from[j]
                        : rig->anims[i]->phase[0].to[j] + rig->anims[i]->len -
                              rig->anims[i]->phase[0].from[j];
            }
            rig->anims[i]->rate =
                rig->anims[i]->unk4 / FUN_L04_001f1978(rig->anims[i]->len + rig->anims[i]->len);
        }
    }
    joints[0] = rig->legs[0].joint;
    joints[1] = rig->legs[0].joint2;
    joints[2] = rig->legs[1].joint;
    joints[3] = rig->legs[1].joint2;
    joints[4] = rig->jointB4;
    joints[5] = rig->jointB5;
    transform_scaled_vertex_batch(moby, 6, joints, rig);
    for (k = 0; k < 2; k++) {
        build_moby_bone_transform(moby, rig->legs[k].joint, matrix[0]);
        rig->legs[k].upper_turn = 0;
        rig->legs[k].lower_turn = 0;
        rig->legs[k].yaw = fast_arc_tan(matrix[1][0], matrix[1][1]);
        if (rig->legs[k].manip_b.attached == 0)
            attach_manipulator(moby, rig->legs[k].slot_b, &rig->legs[k].manip_b);
        if (rig->legs[k].manip_a.attached == 0)
            attach_manipulator(moby, rig->legs[k].slot_a, &rig->legs[k].manip_a);
    }
    rig->unkEE = 0;
    rig->unkB7 = 0;
    rig->unkB8 = 0;
    rig->unkBC = 0;
    rig->speed = 0.0f;
    rig->unkC8 = 0;
    rig->unkE8 = 0;
    rig->unkD8 = 0;
    rig->unkE4 = 0;
    rig->unkEC = 0;
    rig->mode = 5;
    debug_print(rig_size_message, 0x250);
}
