int update_leg_rig_height_and_tilt(StMoby *moby, Steer *steer_state) __asm__("FUN_L04_00292828");

int update_leg_rig_height_and_tilt(StMoby *moby, Steer *steer_state) {
    float push[4];
    float tilt_direction[4];
    int   excessive_tilt_flags = 0;
    int   pinned = 0;
    int   bit = 1;
    int   j;
    float dz;
    float height_correction_divisor;
    float ground_height;
    float sum;
    float xy_abs_sum_or_tilt;

    dz = 0.0f;
    height_correction_divisor = dz;
    if (steer_state->flags & 4) {
        ground_height = probe_ground_height(&moby->pos, 0, 0.5f);
        if (moby->pos.z < ground_height - 0.05f) {
            dz = moby->pos.z - ground_height;
        } else {
            if (steer_state->vel < dz && moby->pos.z < ground_height + 0.1f - steer_state->vel) {
                dz = ground_height - moby->pos.z;
            } else {
                dz = -1.0f;
            }
        }
        steer_state->tilt = 0.0f;
    } else {
        clear_u64_value(push);
        sum = 0.0f;
        for (j = 0; j < 4; j++) {
            Vec *probe_point = &steer_state->pts[j];
            if (steer_state->mask & bit) {
                ground_height = probe_leg_rig_ground_height((float *)probe_point);
                sum += ground_height;
                if (0.0f < ground_height) {
                    xy_abs_sum_or_tilt = absolute_float(coll_hit.normal_x);
                    xy_abs_sum_or_tilt = xy_abs_sum_or_tilt + absolute_float(coll_hit.normal_y);
                    if (xy_abs_sum_or_tilt < absolute_float(coll_hit.normal_z)) {
                        fast_vec_add(push, push, &coll_hit.normal_x);
                        height_correction_divisor += 4.0f;
                        dz += ground_height - probe_point->z;
                    }
                }
            }
            j++;
            bit <<= 2;
        }
        if (sum == 0.0f) {
            ground_height = probe_ground_height(&moby->pos, 0, 0.5f);
            if (0.0f < ground_height) {
                height_correction_divisor += 4.0f;
                dz += ground_height - moby->pos.z;
            }
        }
        if (push[0] != 0.0f || push[1] != 0.0f || push[2] != 0.0f) {
            tilt_direction[0] = fast_cos(moby->rotz);
            tilt_direction[1] = fast_sin(moby->rotz);
            tilt_direction[2] = 0.0f;
            fast_vec_cross(tilt_direction, tilt_direction, push);
            fast_vec_cross(tilt_direction, tilt_direction, push);
            steer_state->tilt = fast_arc_tan(vector_length_xy(tilt_direction), tilt_direction[2]);
        } else {
            steer_state->tilt = 0.0f;
        }
        if (0.785398f < absolute_float(steer_state->tilt)) {
            excessive_tilt_flags = 2;
        }
        if (steer_state->kind == 0xD && 0.0f < steer_state->ground &&
            (steer_state->mask & 0xF) == 0) {
            xy_abs_sum_or_tilt =
                -fast_arc_tan(steer_state->f8C[1], steer_state->ground - moby->pos.z);
            if (absolute_float(xy_abs_sum_or_tilt) < 0.5235988f) {
                pinned = 1;
                dz += steer_state->ground - moby->pos.z;
                steer_state->tilt = xy_abs_sum_or_tilt;
                height_correction_divisor += 4.0f;
            }
        }
    }
    if (height_correction_divisor != 0.0f) {
        dz = dz / height_correction_divisor;
    }
    if (steer_state->flags & 8) {
        if (dz < -0.025f) {
            dz = 0.0f;
        }
        steer_state->vel = 0.0f;
    } else if (-0.025f < dz) {
        if (0.025f < dz && pinned == 0) {
            dz = 0.0f;
        }
        steer_state->vel = 0.0f;
    } else {
        steer_state->vel = steer_state->vel - steer_state->accel;
        dz = steer_state->vel;
    }
    for (j = 0; j < 6; j++) {
        Vec *point_to_shift = &steer_state->pts[j];
        point_to_shift->z += dz;
    }
    moby->pos.z = moby->pos.z + dz;
    return excessive_tilt_flags;
}

extern float rig_turn_2d48(float, float, float *, float, float, float) __asm__("FUN_L00_00258110");

void FUN_L04_00292d48(struct Moby *moby, LegRig *rig, int flags) {
    float      joint[16];
    float      tilt[4];
    float      twist;
    float      base_yaw;
    float      heading;
    LegRigLeg *leg;
    int        mask;
    int        i;

    mask = 3;
    for (i = 0; i < 2; i++) {
        leg = &rig->legs[i];
        build_moby_bone_transform(moby, leg->joint, joint);
        heading = fast_arc_tan(joint[4], joint[5]);
        twist = fast_add_rotations(
            fast_add_rotations(fast_subtract_rotations(leg->yaw, heading), leg->upper_turn),
            leg->lower_turn);
        base_yaw = fast_subtract_rotations(heading, twist);
        if (rig->unkB7 == 0 || (flags & mask) == 0) {
            leg->upper_turn = rig_turn_2d48(leg->upper_turn,
                                            0.0f,
                                            &rig->legs[i].upper_turn_speed,
                                            0.1f,
                                            0.1f,
                                            frame_scale * 0.034906585f);
            leg->lower_turn = rig_turn_2d48(leg->lower_turn,
                                            0.0f,
                                            &rig->legs[i].lower_turn_speed,
                                            0.1f,
                                            0.1f,
                                            frame_scale * 0.034906585f);
        } else {
            if (rig->unkB7 == 13)
                leg->upper_turn = rig_turn_2d48(leg->upper_turn,
                                                0.0f,
                                                &rig->legs[i].upper_turn_speed,
                                                0.1f,
                                                0.1f,
                                                frame_scale * 0.034906585f);
            else
                leg->upper_turn = rig_turn_2d48(leg->upper_turn,
                                                twist * 0.5f,
                                                &rig->legs[i].upper_turn_speed,
                                                0.1f,
                                                0.1f,
                                                frame_scale * 0.034906585f);
            leg->lower_turn = fast_subtract_rotations(twist, leg->upper_turn);
            leg->lower_turn_speed = 0.0f;
        }
        if (rig->legs[i].upper_turn < rig->legs[i].angle_min)
            rig->legs[i].upper_turn = rig->legs[i].angle_min;
        if (rig->legs[i].upper_turn > rig->legs[i].angle_max)
            rig->legs[i].upper_turn = rig->legs[i].angle_max;
        if (rig->legs[i].lower_turn < rig->legs[i].angle_min)
            rig->legs[i].lower_turn = rig->legs[i].angle_min;
        if (rig->legs[i].lower_turn > rig->legs[i].angle_max)
            rig->legs[i].lower_turn = rig->legs[i].angle_max;
        rig->legs[i].yaw = fast_add_rotations(rig->legs[i].upper_turn, base_yaw);
        rig->legs[i].yaw = fast_add_rotations(rig->legs[i].lower_turn, rig->legs[i].yaw);
        if (rig->legs[i].manip_b.attached)
            rotation_2D5FA8(rig->legs[i].manip_b.rot, 2, rig->legs[i].upper_turn);
        if (rig->legs[i].manip_a.attached) {
            rotation_2D5FA8(rig->legs[i].manip_a.rot, 2, rig->legs[i].lower_turn);
            if (flags & mask) {
                rotation_2D5FA8(tilt, 0, -moby->rot.x);
                multiply_quaternions(rig->legs[i].manip_a.rot, rig->legs[i].manip_a.rot, tilt);
            }
        }
        mask <<= 2;
    }
}

